import{_ as t,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年8月27日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-27.md","filePath":"science-log/src/reconstructed/2026-08-27.md"}'),s={name:"science-log/src/reconstructed/2026-08-27.md"};function a(g,o,c,i,d,u){return r(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="🔬-科学快报-2026年8月27日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月27日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月27日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月27日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-08-27 为<strong>周四</strong>。CrossRef 当日命中：Nature（0028-0836）仅 8 条且<strong>全部为 <code>10.1038/d41586-…</code> 新闻 / Daily briefing</strong>，<strong>无一条 <code>s41586</code> 研究论文</strong>（该刊本周研究论文的 <code>published</code> 落在 08-25 / 08-26），故本日科学版<strong>不取 Nature</strong>；Science 系（10.1126）当日命中 <strong>46 条</strong>（含 <code>z…</code> 新闻稿与社论，已剔除），研究论文充足；PNAS（0027-8424）当日命中 <strong>10 条</strong>研究论文。<strong>科学 5 篇</strong>取自 Science / PNAS 当日（<code>published</code> = 2026-08-27）研究论文；<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（<code>submittedDate [202608270000 TO 202608272359]</code> 命中 30 篇，恰好触及 <code>max_results</code> 上限）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-用深度学习从头设计-rna-假结-生成式-ai-在盲测中追平人类专家" tabindex="-1">🧬 用深度学习从头设计 RNA 假结：生成式 AI 在盲测中追平人类专家 <a class="header-anchor" href="#🧬-用深度学习从头设计-rna-假结-生成式-ai-在盲测中追平人类专家" aria-label="Permalink to &quot;🧬 用深度学习从头设计 RNA 假结：生成式 AI 在盲测中追平人类专家&quot;">​</a></h3><p><strong>De novo design of RNA pseudoknots with deep learning</strong><em>Science（2026）</em></p><p>RNA 设计长期受限于三维结构预测精度。本文转向<strong>假结（pseudoknot）二级结构</strong>这一足够复杂、又可用现有工具可靠判定的目标，证明<strong>复杂 RNA 结构可以被从头设计出来</strong>。作者在 <strong>Eterna</strong> 平台上组织了一场涉及 <strong>57 个假结</strong>的竞赛，让生成式 AI 方法与有经验的人类设计者同台盲解；评价手段包括<strong>单核苷酸分辨率的化学映射、补偿性突变、以及冷冻电镜（cryo-EM）</strong>。结果显示生成式 AI 在多数盲题上与人类高手打成平手，AI 生成的分子不仅二级结构准确，还折叠成<strong>由非经典三级相互作用稳定</strong>的良好有序三维构象。这项工作由 27 位作者合作完成（含蛋白设计领域知名学者 David Baker）。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aeg6829" target="_blank" rel="noreferrer">10.1126/science.aeg6829</a></p><h3 id="🦴-trace-不依赖参考基因组与外来群-从祖先重组图中捞出-幽灵-古人类血缘" tabindex="-1">🦴 TRACE：不依赖参考基因组与外来群，从祖先重组图中捞出&quot;幽灵&quot;古人类血缘 <a class="header-anchor" href="#🦴-trace-不依赖参考基因组与外来群-从祖先重组图中捞出-幽灵-古人类血缘" aria-label="Permalink to &quot;🦴 TRACE：不依赖参考基因组与外来群，从祖先重组图中捞出&quot;幽灵&quot;古人类血缘&quot;">​</a></h3><p><strong>Recovering signatures of archaic hominin introgression using ancestral recombination graphs</strong><em>Science（2026）</em></p><p>现代人基因组中留有已灭绝古人类（尼安德特人、丹尼索瓦人）的混血印记，但重建这段历史一直受制于<strong>古样本稀少、且缺少&quot;未混合&quot;的外来群</strong>。作者提出 <strong>TRACE</strong>：一种<strong>既不需要参考基因组、也不需要外来群</strong>的方法，改用<strong>祖先重组图（ARG）<strong>的结构特征来识别古人类血缘。模拟显示 TRACE <strong>精度高、假发现率低</strong>；应用于 <strong>1000 基因组</strong>数据时，它既复现了已知的尼安德特 / 丹尼索瓦混血信号，还</strong>在非洲人与非非洲人中同时找出未被刻画过的&quot;幽灵&quot;古人类混血</strong>，且该幽灵血缘在尼安德特人基因组中持续存在。这为新混血事件与&quot;缺失的近亲&quot;提供了无需古 DNA 的检索工具。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aef8874" target="_blank" rel="noreferrer">10.1126/science.aef8874</a></p><h3 id="⚡-直接蒸发长出单晶金属电极-二维半导体接触瓶颈的新解法" tabindex="-1">⚡ 直接蒸发长出单晶金属电极：二维半导体接触瓶颈的新解法 <a class="header-anchor" href="#⚡-直接蒸发长出单晶金属电极-二维半导体接触瓶颈的新解法" aria-label="Permalink to &quot;⚡ 直接蒸发长出单晶金属电极：二维半导体接触瓶颈的新解法&quot;">​</a></h3><p><strong>Direct evaporation of single-crystal metal contacts for 2D semiconductors</strong><em>Science（2026）</em></p><p>金属—半导体接触是二维半导体电子学的关键瓶颈（势垒高、界面脏、接触电阻大）。作者开发了一套<strong>原子级、分步进行的蒸发方法</strong>，直接在单层半导体上生长<strong>单晶金属</strong>，得到<strong>洁净界面</strong>。其关键在于进入一个特殊的<strong>生长动力学窗口</strong>：<strong>抑制二次成核、促进横向合并</strong>，从而实现铋、银、铟、金、钯等多种金属在 <strong>MoS₂ 与 WSe₂</strong> 上的<strong>范德瓦耳斯外延</strong>。单晶金属支撑起<strong>超薄导电层</strong>，与传统多晶/无序金属接触的形貌与电学行为截然不同，为二维器件把&quot;接触&quot;从工艺难题变成可控的材料设计问题。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aee3132" target="_blank" rel="noreferrer">10.1126/science.aee3132</a></p><h3 id="🌊-注入诱发地震-92-有前震-加拿大西部-77-条序列给出-红绿灯-新判据" tabindex="-1">🌊 注入诱发地震 92% 有前震：加拿大西部 77 条序列给出&quot;红绿灯&quot;新判据 <a class="header-anchor" href="#🌊-注入诱发地震-92-有前震-加拿大西部-77-条序列给出-红绿灯-新判据" aria-label="Permalink to &quot;🌊 注入诱发地震 92% 有前震：加拿大西部 77 条序列给出&quot;红绿灯&quot;新判据&quot;">​</a></h3><p><strong>Foreshock productivity and rupture nucleation in injection-induced earthquakes in western Canada</strong><em>Science（2026）</em></p><p>前震活动是<strong>红绿灯协议（TLP）<strong>缓解注入诱发地震（IIE）风险的关键考量，但 IIE 前震的孕震过程一直不清楚。作者用 <strong>2014–2024 年加拿大西部增强目录</strong>，统计分析了 <strong>77 条 IIE 序列</strong>在局部震级 <strong>M_L ≥ 3</strong> 主震之前的前震形态。结果显示 <strong>92% 的主震之前都有前震</strong>，且</strong>前震的产出率与时空格局</strong>反映了<strong>流体注入、孕震指数（seismogenic index）与断层应力状态</strong>三者的相互作用。逐序列分析提示：主震并非凭空出现，而是<strong>可被前震信号提前指示的成核过程</strong>，这为把前震统计纳入注入作业的风险阈值提供了观测依据。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aed9893" target="_blank" rel="noreferrer">10.1126/science.aed9893</a></p><h3 id="🎲-给香农信息论装上-逻辑推理-压缩极限之外的另一类基本极限" tabindex="-1">🎲 给香农信息论装上&quot;逻辑推理&quot;：压缩极限之外的另一类基本极限 <a class="header-anchor" href="#🎲-给香农信息论装上-逻辑推理-压缩极限之外的另一类基本极限" aria-label="Permalink to &quot;🎲 给香农信息论装上&quot;逻辑推理&quot;：压缩极限之外的另一类基本极限&quot;">​</a></h3><p><strong>Fundamental limits incorporating logical reasoning into Shannon&#39;s information theory</strong><em>PNAS（2026）</em></p><p>香农信息论的奠基性思路是<strong>把消息的&quot;含义&quot;与&quot;高效传输&quot;解耦</strong>：来自随机源的消息，其压缩极限就是信源的熵。本文提出<strong>香农通信模型的推广</strong>：假设<strong>发送方与接收方都具备推理能力</strong>，从而把<strong>信息论与数理逻辑</strong>耦合起来。作者研究的不是&quot;消息本身&quot;，而是<strong>接收方能够从消息中推出的逻辑结论</strong>，并在此设定下刻画新的基本极限。这为&quot;语义通信 / 推理型压缩&quot;这类问题给出了可分析的框架——当双方都会推理时，&quot;传什么&quot;与&quot;能推出什么&quot;是两套不同的问题。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2525600123" target="_blank" rel="noreferrer">10.1073/pnas.2525600123</a></p>',23)])])}const h=t(s,[["render",a]]);export{p as __pageData,h as default};
